### Python

```python
import sys

def main():
    data = list(map(int, sys.stdin.read().strip().split()))
    it = iter(data)
    n = next(it); q = next(it)
    x = [0]*(n+1)
    y = [0]*(n+1)
    z = [0]*(n+1)
    for i in range(1, n+1):
        x[i] = next(it)
    for i in range(1, n+1):
        y[i] = next(it)
    for i in range(1, n+1):
        z[i] = next(it)

    R = [0]*(n+1)
    C = [0]*(n+1)
    for i in range(1, n+1):
        xi, yi, zi = x[i], y[i], z[i]
        # 依据四种唯一情况确定 r_i, c_i
        if zi == 0:
            R[i] = 0
            C[i] = 0
        elif zi == xi:
            R[i] = xi
            C[i] = 0
        elif zi == yi:
            R[i] = 0
            C[i] = yi
        else:
            # 必为 xi ^ yi
            R[i] = xi
            C[i] = yi

    out = []
    for _ in range(q):
        u = next(it); v = next(it)
        out.append(str(R[u] ^ C[v]))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

